package com.secman.service

import com.secman.domain.AnswerType
import com.secman.domain.Requirement
import com.secman.domain.RiskAssessment
import com.secman.dto.Recommendation
import com.secman.dto.RecommendationFinding
import com.secman.dto.RiskAssessmentRecommendation
import com.secman.repository.ResponseRepository
import io.micronaut.transaction.annotation.Transactional
import jakarta.inject.Singleton
import java.time.Instant

/**
 * Deterministic, read-only recommendation shared by the MCP evaluation tool and
 * the REST recommendation endpoint. The caller performs authorization; the
 * [assessment] passed in is already access-checked. Nothing here mutates state,
 * so the result is always advisory and pinned to the assessment's
 * [RiskAssessment.answerRevision].
 */
@Singleton
open class RiskAssessmentRecommendationService(
    private val responseRepository: ResponseRepository,
    private val workflow: AssessmentWorkflowService
) {
    fun requirementsFor(assessment: RiskAssessment): List<Requirement> = workflow.requirementsFor(assessment)

    @Transactional(readOnly = true)
    open fun recommend(assessment: RiskAssessment): RiskAssessmentRecommendation {
        val requirements = requirementsFor(assessment)
        val responses = responseRepository.findByRiskAssessmentId(assessment.id!!).associateBy { it.requirement.id }
        // Legacy MCP semantics: counts cover every stored response, verdict only
        // ever flips on an explicit NO.
        val answerCounts = AnswerType.entries.associate { type ->
            type.name to responses.values.count { it.answerType == type }
        }
        val noCount = answerCounts.getValue(AnswerType.NO.name)
        val naCount = answerCounts.getValue(AnswerType.N_A.name)
        val missingCount = requirements.count { responses[it.id]?.answerType == null }
        val findings = requirements.sortedBy { it.id }.mapNotNull { requirement ->
            val response = responses[requirement.id]
            when (response?.answerType) {
                AnswerType.YES -> null
                AnswerType.NO -> RecommendationFinding(
                    requirementId = requirement.id!!,
                    internalId = requirement.internalId,
                    shortreq = requirement.shortreq,
                    answerType = AnswerType.NO.name,
                    reason = "Requirement is explicitly not met.",
                    comment = response.comment
                )
                AnswerType.N_A -> RecommendationFinding(
                    requirementId = requirement.id!!,
                    internalId = requirement.internalId,
                    shortreq = requirement.shortreq,
                    answerType = AnswerType.N_A.name,
                    reason = "Marked not applicable - reviewer should confirm scope.",
                    comment = response.comment
                )
                null -> RecommendationFinding(
                    requirementId = requirement.id!!,
                    internalId = requirement.internalId,
                    shortreq = requirement.shortreq,
                    answerType = null,
                    reason = "No answer submitted.",
                    comment = response?.comment
                )
            }
        }
        val recommendation = when {
            noCount > 0 -> Recommendation.NOT_OK
            assessment.status != "COMPLETED" -> Recommendation.NEEDS_REVIEW
            missingCount > 0 -> Recommendation.NEEDS_REVIEW
            requirements.isEmpty() -> Recommendation.NEEDS_REVIEW
            else -> Recommendation.OK
        }
        return RiskAssessmentRecommendation(
            assessmentId = assessment.id!!,
            answerRevision = assessment.answerRevision,
            recommendation = recommendation,
            verdict = if (noCount == 0) "COMPLIANT" else "NON_COMPLIANT",
            summary = summary(recommendation, assessment.status, requirements.size, missingCount, noCount, naCount),
            answerCounts = answerCounts,
            requirementCount = requirements.size,
            missingAnswerCount = missingCount,
            findings = findings,
            generatedAt = Instant.now(),
            policyVersion = POLICY_VERSION
        )
    }

    private fun summary(
        recommendation: Recommendation,
        status: String,
        requirementCount: Int,
        missingCount: Int,
        noCount: Int,
        naCount: Int
    ): String {
        val answeredCount = requirementCount - missingCount
        return when (recommendation) {
            Recommendation.NOT_OK -> buildList {
                add("$noCount ${if (noCount == 1) "requirement is" else "requirements are"} not met")
                if (missingCount > 0) add("$missingCount ${if (missingCount == 1) "answer needs" else "answers need"} review")
                if (naCount > 0) add("$naCount marked not applicable")
            }.joinToString("; ", postfix = ".")
            Recommendation.NEEDS_REVIEW -> when {
                status != "COMPLETED" ->
                    "Questionnaire is not yet submitted; $answeredCount of $requirementCount requirements answered."
                missingCount > 0 ->
                    "Questionnaire is submitted but incomplete; $answeredCount of $requirementCount requirements answered."
                else -> "No requirements are in scope for this assessment."
            }
            Recommendation.OK -> if (naCount > 0) {
                "All $requirementCount requirements are answered and none are unmet; $naCount marked not applicable."
            } else {
                "All $requirementCount requirements are answered and none are unmet."
            }
        }
    }

    companion object {
        const val POLICY_VERSION = "1.0"
    }
}
package com.secman.dto

import io.micronaut.serde.annotation.Serdeable
import java.time.Instant

/**
 * Shared deterministic risk-assessment recommendation, computed once by
 * [com.secman.service.RiskAssessmentRecommendationService] and served on both
 * the MCP `evaluate_risk_assessment` surface and REST
 * `GET /api/risk-assessments/{id}/recommendation`. Advisory only — acceptance
 * stays with an independent human reviewer.
 */

@Serdeable
enum class Recommendation {
    OK,
    NOT_OK,
    NEEDS_REVIEW
}

@Serdeable
data class RecommendationFinding(
    val requirementId: Long,
    val internalId: String?,
    val shortreq: String?,
    val answerType: String?,
    val reason: String,
    val comment: String?
)

@Serdeable
data class RiskAssessmentRecommendation(
    val assessmentId: Long,
    val answerRevision: Long,
    val recommendation: Recommendation,
    val verdict: String,
    val summary: String,
    val answerCounts: Map<String, Int>,
    val requirementCount: Int,
    val missingAnswerCount: Int,
    val findings: List<RecommendationFinding>,
    val generatedAt: Instant,
    val advisory: Boolean = true,
    val policyVersion: String
)
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { authenticatedGet } from '../utils/auth';
import { formatServerDateTime } from '../utils/dateUtils';

type Recommendation = 'OK' | 'NOT_OK' | 'NEEDS_REVIEW';

interface RecommendationFinding {
  requirementId: number;
  internalId?: string | null;
  shortreq?: string | null;
  answerType: string | null;
  reason: string;
  comment?: string | null;
}

interface AssessmentRecommendation {
  assessmentId: number;
  answerRevision: number;
  recommendation: Recommendation;
  verdict: 'COMPLIANT' | 'NON_COMPLIANT';
  summary: string;
  answerCounts: Record<string, number>;
  requirementCount: number;
  missingAnswerCount: number;
  findings: RecommendationFinding[];
  generatedAt: string;
  advisory: boolean;
  policyVersion: string;
}

interface Props {
  assessmentId: number;
  assessmentLabel?: string;
  onClose: () => void;
  onReviewAnswers?: () => void;
}

const RECOMMENDATION_BADGES: Record<Recommendation, { className: string; icon: string; text: string }> = {
  OK: { className: 'bg-success', icon: '✓', text: 'OK' },
  NOT_OK: { className: 'bg-danger', icon: '✗', text: 'Not OK' },
  NEEDS_REVIEW: { className: 'bg-warning text-dark', icon: '!', text: 'Needs review' },
};

const FALLBACK_BADGE = { className: 'bg-secondary', icon: '?', text: 'Unknown recommendation' };

const answerTypeBadge = (answerType: string | null): { className: string; text: string } => {
  switch (answerType) {
    case 'NO':
      return { className: 'bg-danger', text: 'No' };
    case 'N_A':
      return { className: 'bg-secondary', text: 'N/A' };
    case 'YES':
      return { className: 'bg-success', text: 'Yes' };
    default:
      return { className: 'bg-warning text-dark', text: 'No answer submitted' };
  }
};

const AssessmentRecommendationModal: React.FC<Props> = ({
  assessmentId,
  assessmentLabel,
  onClose,
  onReviewAnswers,
}) => {
  const [data, setData] = useState<AssessmentRecommendation | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<{ message: string; retryable: boolean } | null>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  const fetchRecommendation = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await authenticatedGet(`/api/risk-assessments/${assessmentId}/recommendation`);
      if (response.ok) {
        setData(await response.json());
      } else if (response.status === 403) {
        setData(null);
        setError({ message: "You don't have review authority for this assessment.", retryable: false });
      } else if (response.status === 404) {
        setData(null);
        setError({ message: 'Assessment not found or not visible to you.', retryable: false });
      } else {
        setData(null);
        setError({ message: `Could not analyze the answers (server responded with status ${response.status}).`, retryable: true });
      }
    } catch (err) {
      setData(null);
      setError({ message: err instanceof Error ? err.message : 'Could not analyze the answers.', retryable: true });
    } finally {
      setLoading(false);
    }
  }, [assessmentId]);

  useEffect(() => {
    fetchRecommendation();
  }, [fetchRecommendation]);

  useEffect(() => {
    dialogRef.current?.focus();
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onClose]);

  const badge = data ? (RECOMMENDATION_BADGES[data.recommendation] ?? FALLBACK_BADGE) : null;

  return (
    <div
      className="modal show fade d-block"
      tabIndex={-1}
      role="dialog"
      aria-modal="true"
      aria-labelledby="assessmentRecommendationModalTitle"
      ref={dialogRef}
      style={{ backgroundColor: 'var(--scand-overlay)' }}
    >
      <div className="modal-dialog modal-lg" role="document">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title" id="assessmentRecommendationModalTitle">
              Analyze answers{assessmentLabel ? ` — ${assessmentLabel}` : ''}
            </h5>
            <button type="button" className="btn-close" aria-label="Close" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            {loading && (
              <div className="d-flex align-items-center gap-2">
                <div className="spinner-border spinner-border-sm" role="status">
                  <span className="visually-hidden">Loading...</span>
                </div>
                <span>Analyzing answers...</span>
              </div>
            )}

            {!loading && error && (
              <div className="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
                <span>{error.message}</span>
                {error.retryable && (
                  <button type="button" className="btn btn-outline-danger btn-sm" onClick={fetchRecommendation}>
                    Retry
                  </button>
                )}
              </div>
            )}

            {!loading && !error && data && badge && (
              <>
                <div className="d-flex align-items-center flex-wrap gap-2 mb-3">
                  <span
                    className={`badge fs-6 ${badge.className}`}
                    role="status"
                    aria-label={`Recommendation: ${badge.text}`}
                  >
                    <span aria-hidden="true">{badge.icon}</span> {badge.text}
                  </span>
                  <small className="text-muted">Advisory — human approval is still required</small>
                </div>

                <p>{data.summary}</p>

                <h6 className="text-muted">Answer counts</h6>
                <dl className="row small mb-3">
                  <dt className="col-sm-4">Answered &quot;Yes&quot;</dt>
                  <dd className="col-sm-8">{data.answerCounts.YES ?? 0}</dd>
                  <dt className="col-sm-4">Answered &quot;No&quot;</dt>
                  <dd className="col-sm-8">{data.answerCounts.NO ?? 0}</dd>
                  <dt className="col-sm-4">Answered &quot;N/A&quot;</dt>
                  <dd className="col-sm-8">{data.answerCounts.N_A ?? 0}</dd>
                  <dt className="col-sm-4">Missing answers</dt>
                  <dd className="col-sm-8">{data.missingAnswerCount}</dd>
                  <dt className="col-sm-4">Requirements in scope</dt>
                  <dd className="col-sm-8">{data.requirementCount}</dd>
                </dl>

                <h6 className="text-muted">Findings</h6>
                {data.findings.length === 0 ? (
                  <p className="text-muted">No findings — every requirement is answered and none are unmet.</p>
                ) : (
                  <ul className="list-group">
                    {data.findings.map(finding => {
                      const answerBadge = answerTypeBadge(finding.answerType);
                      return (
                        <li key={finding.requirementId} className="list-group-item">
                          <div className="d-flex justify-content-between align-items-start gap-2">
                            <strong>{finding.internalId || `Requirement #${finding.requirementId}`}</strong>
                            <span className={`badge ${answerBadge.className}`}>{answerBadge.text}</span>
                          </div>
                          {finding.shortreq && <div>{finding.shortreq}</div>}
                          <div className="small">{finding.reason}</div>
                          {finding.comment && (
                            <div className="small text-muted">Comment: {finding.comment}</div>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                )}
              </>
            )}
          </div>
          <div className="modal-footer d-flex justify-content-between align-items-center flex-wrap gap-2">
            <small className="text-muted">
              {data
                ? `Answer revision ${data.answerRevision} · Policy v${data.policyVersion} · Generated ${formatServerDateTime(data.generatedAt)}`
                : ''}
            </small>
            <div className="d-flex gap-2">
              <button type="button" className="btn btn-outline-primary" onClick={fetchRecommendation} disabled={loading}>
                Refresh
              </button>
              {onReviewAnswers && (
                <button type="button" className="btn btn-outline-warning" onClick={onReviewAnswers}>
                  Review answers
                </button>
              )}
              <button type="button" className="btn btn-secondary" onClick={onClose}>
                Close
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AssessmentRecommendationModal;

