import React, { useCallback, useEffect, useRef, useState } from 'react';
import { authenticatedGet } from '../utils/auth';
import { formatServerDateTime } from '../utils/dateUtils';

type Recommendation = 'OK' | 'NOT_OK' | 'NEEDS_REVIEW';

