            riskAssessmentId = info.riskAssessmentId,
            useCases = resolution.useCases.map { it.name }.sorted(),
            requirementCount = resolution.requirementCount,
            deadline = formatDate(endDate),
            matchedRules = resolution.matchedRuleNames
