api() {
    local method="$1" path="$2" body="${3:-}" output_file
    output_file="$(mktemp)"
    local args=(-sS -o "$output_file" -w '%{http_code}' -b "$COOKIE_JAR" -X "$method" "${BASE_URL}${path}")
    [[ -z "$body" ]] || args+=(-H 'Content-Type: application/json' --data "$body")
    API_STATUS="$(curl "${args[@]}")"
    command cat "$output_file"
    command rm -f "$output_file"
}

mcp_call() {
    local tool="$1" arguments="$2" delegated_email="$3" body response
    body="$(jq -nc --arg tool "$tool" --argjson args "$arguments" --arg id "e2e-${RANDOM}" \
        '{jsonrpc:"2.0",id:$id,method:"tools/call",params:{name:$tool,arguments:$args}}')"
    response="$(curl -sS -X POST "${BASE_URL}/mcp" \
  };

  const handleCheckAnswers = (assessment: RiskAssessment, requirementId?: number) => {
    setFocusedRequirementId(requirementId);
    if (!assessment.id) {
      setError('Invalid assessment ID');
      return;
    }
    setSelectedAssessmentId(assessment.id);
    setAssessmentModalMode('review');
    setShowAssessmentModal(true);
  };

  // Deep link from the notification emails: /risk-assessments?assessmentId=42 opens that
  // assessment straight away instead of leaving the recipient to find it in the list.
  // Runs once the list has loaded, because the id is only honoured when it is actually
  // among the assessments this user may see — the list is already access-filtered by the
  // backend, so this cannot be used to peek at someone else's assessment.
  const [deepLinkHandled, setDeepLinkHandled] = useState(false);
  useEffect(() => {
    if (deepLinkHandled || loading || typeof window === 'undefined') return;
        || log_fail "expected 0 assessments for $GUIDED_ACCOUNT, found $count"
}

phase_owner_flow() {
    phase "Public: the owner opens the link, answers, and gets one assessment scoped to the union"

    local token; token=$(capture_token "$GUIDED_ACCOUNT")
    if [[ -z "$token" ]]; then
        log_warn "Could not recover an invite token (backend log not available) — owner-flow phases skipped"
        return 0
    fi
    log_dbg "Using invite token $(redact_token "$token")"

    local body
    body=$(public_api GET "/api/public/account-onboarding/${token}")
    [[ "$PUBLIC_STATUS" == "200" ]] && log_pass "questionnaire GET returned 200" \
        || { log_fail "questionnaire GET returned $PUBLIC_STATUS"; return 0; }

    local masked
    masked=$(echo "$body" | jq -r '.maskedAccountId // empty')
    [[ "$masked" == "****${GUIDED_ACCOUNT: -4}" ]] \
        && log_pass "the account id is masked ($masked)" \
        || log_fail "expected a masked account id, got '$masked'"
    if echo "$body" | grep -q "$GUIDED_ACCOUNT"; then
        log_fail "the full account id leaked to an unauthenticated caller"
"}

