package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.dto.mcp.McpExecutionContext
import com.secman.service.OwnerMailDeliveryService
import jakarta.inject.Singleton

@Singleton
class ListOwnerMailNotificationsTool(private val service: OwnerMailDeliveryService) : McpTool {
    override val name = "list_owner_mail_notifications"
    override val description = "List retained AWS owner welcome-mail delivery outcomes (ADMIN only)"
    override val operation = McpOperation.READ
    override val inputSchema = mapOf("type" to "object", "properties" to mapOf(
        "page" to mapOf("type" to "integer", "minimum" to 0),
        "pageSize" to mapOf("type" to "integer", "minimum" to 1, "maximum" to 100)
    ))
    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        requireAnyUserRole(context, "ADMIN", message = "ADMIN delegation required")?.let { return it }
        return riskAssessmentTool { service.list((arguments["page"] as? Number)?.toInt() ?: 0,
            (arguments["pageSize"] as? Number)?.toInt() ?: 20) }
    }
}
package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.dto.mcp.McpExecutionContext
import com.secman.service.OwnerMailDeliveryService
import jakarta.inject.Singleton

@Singleton
class RetryOwnerMailNotificationTool(private val service: OwnerMailDeliveryService) : McpTool {
    override val name = "retry_owner_mail_notification"
    override val description = "Explicitly retry a retained FAILED AWS owner welcome notification (ADMIN only); SENT and uncertain delivery cannot be retried"
    override val operation = McpOperation.WRITE
    override val inputSchema = mapOf("type" to "object", "properties" to mapOf(
        "notificationId" to mapOf("type" to "integer", "minimum" to 1)
    ), "required" to listOf("notificationId"))
    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        requireAnyUserRole(context, "ADMIN", message = "ADMIN delegation required")?.let { return it }
        val id = (arguments["notificationId"] as? Number)?.toLong()
        if (id == null || id < 1) return McpToolResult.error("VALIDATION_ERROR", "notificationId must be a positive integer")
        return riskAssessmentTool { service.retry(id, context.delegatedUserId!!) }
    }
}
package com.secman.controller

import com.secman.service.OwnerMailDeliveryService
import io.micronaut.http.HttpResponse
import io.micronaut.http.HttpStatus
import io.micronaut.http.annotation.*
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication

@Controller("/api/admin/owner-mail-notifications")
@Secured("ADMIN")
@io.micronaut.scheduling.annotation.ExecuteOn(io.micronaut.scheduling.TaskExecutors.BLOCKING)
class OwnerMailNotificationController(private val service: OwnerMailDeliveryService) {
    @Get("{?page,pageSize}")
    fun list(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "20") pageSize: Int): HttpResponse<*> =
        try { HttpResponse.ok(service.list(page, pageSize)) }
        catch (e: IllegalArgumentException) { HttpResponse.badRequest(mapOf("error" to "Invalid page or pageSize")) }

    @Post("/{id}/retry")
    fun retry(id: Long, authentication: Authentication): HttpResponse<*> {
        val actor = (authentication.attributes["userId"] as? Number)?.toLong()
            ?: return HttpResponse.status<Any>(HttpStatus.FORBIDDEN)
        return try { HttpResponse.ok(service.retry(id, actor)) }
        catch (e: NoSuchElementException) { HttpResponse.notFound<Any>() }
        catch (e: IllegalStateException) {
            HttpResponse.status<Any>(HttpStatus.CONFLICT).body(mapOf("error" to "Only retained, failed notifications can be retried"))
        }
    }
}
