package com.secman.mcp.tools

import org.slf4j.LoggerFactory

private val riskAssessmentToolLog = LoggerFactory.getLogger("McpRiskAssessmentTools")

internal inline fun riskAssessmentTool(block: () -> Any): McpToolResult = try {
    McpToolResult.success(block())
} catch (e: NoSuchElementException) {
    McpToolResult.error("NOT_FOUND", e.message ?: "Risk assessment not found")
} catch (e: SecurityException) {
    McpToolResult.error("FORBIDDEN", e.message ?: "Access denied")
} catch (e: IllegalStateException) {
    McpToolResult.error("CONFLICT", e.message ?: "Invalid assessment state")
} catch (e: IllegalArgumentException) {
    McpToolResult.error("VALIDATION_ERROR", e.message ?: "Invalid input")
} catch (e: Exception) {
    riskAssessmentToolLog.error("MCP risk assessment operation failed", e)
    McpToolResult.error("EXECUTION_ERROR", "Risk assessment operation failed")
}
    open fun saveAnswers(
        context: McpExecutionContext,
        assessmentId: Long,
        answers: List<AnswerInput>
    ): Map<String, Any> {
        val initiator = workflow.mcpInitiator(context.apiKeyId, context.delegatedUserId ?: throw SecurityException("Delegation required"))
        val saved = workflow.save(assessmentId, authentication(context), answers.map {
            AssessmentWorkflowService.Answer(it.requirementId, it.answerType, it.comment)
        }, initiator, context.apiKeyId)
        return mapOf("assessmentId" to assessmentId, "savedCount" to saved.size)
    }

    @Transactional
    open fun submit(context: McpExecutionContext, assessmentId: Long): Map<String, Any> {
        workflow.mcpInitiator(context.apiKeyId, context.delegatedUserId ?: throw SecurityException("Delegation required"))
        val assessment = workflow.submit(assessmentId, authentication(context))
        return mapOf("assessmentId" to assessmentId, "status" to assessment.status)
    }

    @Transactional(readOnly = true)
    open fun evaluate(context: McpExecutionContext, assessmentId: Long): Map<String, Any> {
        val assessment = accessibleAssessment(context, assessmentId, lockForRecommendation = true)
        val canEvaluate = access.canAnalyze(assessment, authentication(context))
        if (!canEvaluate) throw SecurityException("Only the assessor, requestor, ADMIN or SECCHAMPION may evaluate")
        check(assessment.status == "COMPLETED") { "Only a completed assessment can be evaluated" }

        val rec = recommendationService.recommend(assessment, completedOnly = true)
        log.info("AUDIT operation=ASSESSMENT_ANALYSIS actorId={} assessmentId={} revision={} outcome={}",
            context.delegatedUserId, assessmentId, rec.answerRevision, rec.recommendation)
        return mapOf(
            "assessment" to assessmentSummary(assessment),
            "verdict" to rec.verdict,
            "answerCounts" to rec.answerCounts,
            "requirementCount" to rec.requirementCount,
            "findings" to rec.findings.map { finding ->
